<?php $isEdit=!empty($appointment);$doctorMode=\App\Core\Auth::role()==='doctor'; ?>
<div class="panel form-panel">
<?php if($doctorMode): ?>
<form method="post" action="<?= url('/appointments/'.$appointment['id'].'/update') ?>" class="form-grid"><?= csrf_field() ?>
<div class="summary-box field-full"><strong>Cita del <?= e(date('d/m/Y',strtotime($appointment['appointment_date']))) ?> a las <?= e(substr($appointment['appointment_time'],0,5)) ?></strong><span>Como médico puedes actualizar el estado y las observaciones.</span></div>
<div class="field"><label>Estado</label><select name="status"><?php foreach(['pending'=>'Pendiente','confirmed'=>'Confirmada','completed'=>'Atendida','cancelled'=>'Cancelada','no_show'=>'No asistió'] as $k=>$v):?><option value="<?= $k ?>" <?= ($appointment['status']??'pending')===$k?'selected':'' ?>><?= e($v) ?></option><?php endforeach;?></select></div><div class="field field-full"><label>Observaciones</label><textarea name="notes" rows="5"><?= e($appointment['notes']??'') ?></textarea></div><div class="form-actions field-full"><a class="btn" href="<?= url('/appointments') ?>">Cancelar</a><button class="btn btn-primary">Guardar cambios</button></div></form>
<?php else: ?>
<form method="post" action="<?= $isEdit?url('/appointments/'.$appointment['id'].'/update'):url('/appointments') ?>" class="form-grid"><?= csrf_field() ?>
<div class="field"><label>Paciente *</label><select name="patient_id" required><option value="">Seleccionar</option><?php foreach($patients as $p):?><option value="<?= $p['id'] ?>" <?= (int)old('patient_id',$appointment['patient_id']??0)===(int)$p['id']?'selected':'' ?>><?= e($p['first_name'].' '.$p['last_name']) ?></option><?php endforeach;?></select></div>
<div class="field"><label>Médico *</label><select name="doctor_id" required><option value="">Seleccionar</option><?php foreach($doctors as $d):?><option value="<?= $d['id'] ?>" <?= (int)old('doctor_id',$appointment['doctor_id']??0)===(int)$d['id']?'selected':'' ?>><?= e($d['name'].' · '.$d['specialty_name']) ?></option><?php endforeach;?></select></div>
<div class="field"><label>Fecha *</label><input type="date" min="<?= date('Y-m-d') ?>" name="appointment_date" value="<?= e(old('appointment_date',$appointment['appointment_date']??date('Y-m-d'))) ?>" required><?php if(error('appointment_date')):?><small class="error-text"><?= e(error('appointment_date')) ?></small><?php endif;?></div>
<div class="field"><label>Hora *</label><input type="time" name="appointment_time" value="<?= e(substr((string)old('appointment_time',$appointment['appointment_time']??'09:00'),0,5)) ?>" step="900" required><?php if(error('appointment_time')):?><small class="error-text"><?= e(error('appointment_time')) ?></small><?php endif;?></div>
<div class="field"><label>Duración</label><select name="duration_minutes"><?php foreach([20,30,45,60] as $m):?><option value="<?= $m ?>" <?= (int)old('duration_minutes',$appointment['duration_minutes']??30)===$m?'selected':'' ?>><?= $m ?> minutos</option><?php endforeach;?></select></div>
<div class="field"><label>Estado</label><select name="status"><?php foreach(['pending'=>'Pendiente','confirmed'=>'Confirmada','completed'=>'Atendida','cancelled'=>'Cancelada','no_show'=>'No asistió'] as $k=>$v):?><option value="<?= $k ?>" <?= old('status',$appointment['status']??'pending')===$k?'selected':'' ?>><?= e($v) ?></option><?php endforeach;?></select></div>
<div class="field field-full"><label>Motivo de consulta *</label><textarea name="reason" rows="3" required><?= e(old('reason',$appointment['reason']??'')) ?></textarea><?php if(error('reason')):?><small class="error-text"><?= e(error('reason')) ?></small><?php endif;?></div>
<div class="field field-full"><label>Observaciones</label><textarea name="notes" rows="3"><?= e(old('notes',$appointment['notes']??'')) ?></textarea></div>
<div class="hint field-full">El sistema verificará que el médico tenga horario disponible y que no exista otra cita en la misma fecha y hora.</div>
<div class="form-actions field-full"><a class="btn" href="<?= url('/appointments') ?>">Cancelar</a><button class="btn btn-primary"><?= $isEdit?'Guardar cambios':'Registrar cita' ?></button></div></form>
<?php endif; ?>
</div>
